			...data,
			id: randomUUID(),
			scopeKind: ctx.scope.kind,
			scopeId: ctx.scope.id,
			createdAt: new Date(),
			retiredAt: null,
			revision: 0,
			leaseToken: null,
			leaseUntil: null,
