			db,
			bindingId,
			ctx,
			"client",
			workerSignal(ctx.signal),
		);
		const [p] = await db
			.select()
			.from(clients)
			.where(eq(clients.bindingId, b.id));
		if (!p) throw new InvoiceNinjaError("not_found");
