			bindingId: b.id,
			remoteId: b.remoteId,
			syncedAt: p.syncedAt.toISOString(),
		};
	}
	async function getInvoice(ctx: TrustedContext, input: unknown) {
		const { bindingId } = parse(bindingRef, input);
		const b = await bound(
			db,
			bindingId,
			ctx,
			"invoice",
			workerSignal(ctx.signal),
		);
		const [p] = await db
			.select()
			.from(invoices)
			.where(eq(invoices.bindingId, b.id));
