import { isIP } from "node:net";
import { InvoiceNinjaError } from "./errors";
import { hasControls, opaqueId, parse } from "./validation";
export const providerPin = {
	version: "5.13.43",
	commit: "382020072bc79e8c7ede49f7e9ce91b0aeb1a051",
