}
export function decodeCursor(s: string): [string, string] {
	try {
		if (s.length > 2048 || !/^[A-Za-z0-9_-]+$/.test(s)) throw 0;
		const bytes = Buffer.from(s, "base64url");
		if (bytes.toString("base64url") !== s) throw 0;
